package com.gk.jobhelper.service;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;import org.springframework.stereotype.Component;
@Component public class RecruitmentFileTypeDetector {
 public String detect(String contentType,String fileName,byte[] bytes){if(starts(bytes,"%PDF".getBytes(StandardCharsets.US_ASCII)))return "PDF";if(ole(bytes))return "XLS";if(zip(bytes))return officeType(bytes);String text=text(bytes),c=contentType==null?"":contentType.toLowerCase();if(c.contains("text/html")||text.toLowerCase().matches("(?s).*<(html|body)\\b.*"))return "HTML";if((text.startsWith("{")&&text.endsWith("}"))||(text.startsWith("[")&&text.endsWith("]")))return "JSON";if(c.contains("spreadsheetml"))return "XLSX";if(c.contains("ms-excel"))return "XLS";return new RecruitmentAttachmentClassifier().fileType(fileName);}
 private boolean ole(byte[] b){return b!=null&&b.length>=8&&b[0]==(byte)0xD0&&b[1]==(byte)0xCF&&b[2]==0x11&&b[3]==(byte)0xE0&&b[4]==(byte)0xA1&&b[5]==(byte)0xB1&&b[6]==0x1A&&b[7]==(byte)0xE1;}private boolean zip(byte[] b){return b!=null&&b.length>=4&&b[0]=='P'&&b[1]=='K'&&(b[2]==3||b[2]==5||b[2]==7);}private String officeType(byte[] b){boolean workbook=false,document=false;try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(b))){ZipEntry e;while((e=in.getNextEntry())!=null){workbook|="xl/workbook.xml".equals(e.getName());document|="word/document.xml".equals(e.getName());}}catch(IOException ignored){return "OTHER";}return workbook?"XLSX":document?"DOCX":"ZIP";}private String text(byte[] b){return b==null?"":new String(b,0,Math.min(4096,b.length),StandardCharsets.UTF_8).replaceFirst("^\\uFEFF","").trim();}private boolean starts(byte[] b,byte[] prefix){if(b==null||b.length<prefix.length)return false;for(int i=0;i<prefix.length;i++)if(b[i]!=prefix[i])return false;return true;}}
